    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    integer i;
    reg [4:0] expected_q;

    // Function to compute expected next state of the Galois LFSR
    function [4:0] next_lfsr(input [4:0] current);
        begin
            next_lfsr = {
                current[0],
                current[4],
                current[3] ^ current[0],
                current[2],
                current[1] ^ current[0]
            };
        end
    endfunction

    initial begin
        // Initialize signals
        reset = 1;
        expected_q = 5'b00001;

        // Apply reset for a few cycles
        @(posedge clk);
        #1;
        if (q !== 5'b00001) begin
            $display("ERROR: Reset failed. Expected 5'b00001, got %b", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        reset = 0;

        // Check a sequence of states (e.g., 35 cycles to cycle through max-length 31 states + extra)
