            // Compute expected state BEFORE the clock edge (based on current q)
            expected_q = next_lfsr(expected_q);

            @(posedge clk);
            #1; // small delay to sample after clock edge

            if (q !== expected_q) begin
                $display("ERROR at cycle %0d: Expected q = %b, got q = %b", i, expected_q, q);
                errors = errors + 1;
            end
        end

        // Test synchronous reset again mid-operation
        @(posedge clk);
        reset = 1;
        expected_q = 5'b00001;
        #1;
        if (q !== 5'b00001) begin
            $display("ERROR: Mid-operation reset failed. Expected 5'b00001, got %b", q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;
        @(posedge clk);
        #1;
        expected_q = next_lfsr(expected_q);
        if (q !== expected_q) begin
            $display("ERROR: Post-reset recovery failed. Expected %b, got %b", expected_q, q);
            errors = errors + 1;
        end

        // Final Result Display
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
